
import json
from pathlib import Path


def write_entrypoint(
    sources,
    destination,
    *,
    kind="js",
    hmr_client=None,
):
    destination = Path(destination)
    destination.parent.mkdir(parents=True, exist_ok=True)

    lines = [
        "// Generated by djangospice.assets. Do not edit.",
    ]

    for item in sources:
        if isinstance(item, dict):
            source = item.get(kind)

        elif isinstance(item, (tuple, list)):
            source = item[-1] if item else None

        else:
            source = item

        if source:
            source = Path(source).resolve().as_posix()

            lines.append(
                f"import {json.dumps(source)};"
            )

    if hmr_client:
        lines.append(
            f"import {json.dumps(Path(hmr_client).resolve().as_posix())};"
        )

    destination.write_text(
        "\n".join(lines) + "\n",
        encoding="utf-8",
    )

    return destination



def write_hmr_client(
    destination,
    *,
    host,
    port,
    path,
):
    """
    Generate the development-only browser HMR client.

    CSS changes replace stylesheet URLs without reloading.
    JavaScript changes trigger a full page reload.
    """

    destination = Path(destination)

    destination.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    destination.write_text(
        f'''// Development-only Djangospice HMR client.
(() => {{
  if (window.__DJANGOSPICE_HMR__) return;

  window.__DJANGOSPICE_HMR__ = true;

  const scheme = location.protocol === "https:" ? "wss" : "ws";
  const host = {json.dumps(host)} || location.hostname;

  const socket = new WebSocket(
    `${{scheme}}://${{host}}:{port}{path}`
  );

  socket.addEventListener("message", (event) => {{
    let message;

    try {{
      message = JSON.parse(event.data);
    }} catch (_) {{
      return;
    }}

    if (message.type === "css") {{
      const links = document.querySelectorAll(
        'link[data-djangospice-assets="css"]'
      );

      if (!links.length || !message.url) {{
        location.reload();
        return;
      }}

      links.forEach((link) => {{
        const url = new URL(message.url, location.href);

        url.searchParams.set(
          "hmr",
          message.version || Date.now().toString()
        );

        link.href = url.toString();
      }});

    }} else if (
      message.type === "js" ||
      message.type === "reload"
    ) {{
      location.reload();
    }}
  }});

  socket.addEventListener("close", () => {{
    // Allow the watch server to restart.
    // Reconnection is handled without forcing a page reload.
    setTimeout(() => {{
      window.__DJANGOSPICE_HMR__ = false;

      if (typeof window.__DJANGOSPICE_HMR_CONNECT__ === "function") {{
        window.__DJANGOSPICE_HMR_CONNECT__();
      }}
    }}, 2000);
  }});
}})();
''',
        encoding="utf-8",
    )

    return destination
